        md_output.dipole_a_m2 = zero_v;
        md_output.torque_nm = zero_v;
        md_output.dissipative_power = 0.0;
        return;
    }
    if (md_input.momentum_nms == NULL || md_input.field_body_t == NULL ||
        !adcs_is_finite_vec3(md_input.momentum_nms) ||
        !adcs_is_finite_vec3(md_input.field_body_t)) {
        md_state.mode = MD_FAULT;
        md_state.elapsed = 0U;
        md_state.saturated_on_cycles = 0U;
        md_state.rest_target = 0U;
        md_output.mode = MD_FAULT;
