    md_output.elapsed = md_state.elapsed;
    md_output.saturation_mask = 0U;
    md_output.dipole_a_m2 = zero_v;
    md_output.torque_nm = zero_v;
    md_output.dissipative_power = 0.0;

    /* 2. Disabled 或 demand 缺失 */
    if (md_input.enable == 0 || md_input.demand == 0) {
        md_state.mode = MD_IDLE;
        md_state.elapsed = 0U;
        md_state.saturated_on_cycles = 0U;
        md_state.rest_target = 0U;
        md_output.mode = MD_IDLE;
        md_output.elapsed = 0U;
        md_output.saturation_mask = 0U;
        md_output.dipole_a_m2 = zero_v;
        md_output.torque_nm = zero_v;
        md_output.dissipative_power = 0.0;
        return;
    }

