    if (md_state.mode == MD_IDLE) {
        md_state.mode = MD_ON;
        md_state.elapsed = 1U;
        md_state.saturated_on_cycles = 0U;
    } else if (md_state.mode == MD_REST) {
        md_state.elapsed++;
        md_output.mode = MD_REST;
        md_output.elapsed = md_state.elapsed;
        md_output.saturation_mask = 0U;
        md_output.dipole_a_m2 = zero_v;
        md_output.torque_nm = zero_v;
        md_output.dissipative_power = 0.0;
        if (md_state.elapsed >= md_state.rest_target) {
            md_state.mode = MD_IDLE;
            md_state.elapsed = 0U;
            md_state.rest_target = 0U;
            md_state.saturated_on_cycles = 0U;
            md_output.mode = MD_IDLE;
            md_output.elapsed = 0U;
        }
        return;
    } else if (md_state.mode == MD_FAULT) {
        md_output.mode = MD_FAULT;
        md_output.elapsed = 0U;
        md_output.saturation_mask = 0U;
        md_output.dipole_a_m2 = zero_v;
        md_output.torque_nm = zero_v;
        md_output.dissipative_power = 0.0;
        return;
    } else {
        md_state.elapsed++;
    }

    /* 4. ON 计算 unload 输出 */
    st = adcs_momentum_unload_dipole(md_input.momentum_nms, md_input.field_body_t,
                                     md_config.gain_s_inv, md_config.max_dipole_a_m2,
                                     &cmd, &tq);
    if (st == ADCS_E_DEGENERATE || st == ADCS_E_NOT_FINITE || st == ADCS_E_RANGE) {
        md_state.mode = MD_FAULT;
        md_state.elapsed = 0U;
        md_state.saturated_on_cycles = 0U;
        md_state.rest_target = 0U;
        md_output.mode = MD_FAULT;
        md_output.elapsed = 0U;
        md_output.saturation_mask = 0U;
        md_output.dipole_a_m2 = zero_v;
        md_output.torque_nm = zero_v;
        md_output.dissipative_power = 0.0;
        return;
    }

    md_output.mode = MD_ON;
    md_output.elapsed = md_state.elapsed;
    md_output.saturation_mask = cmd.saturated_axes;
    md_output.dipole_a_m2 = cmd.command;
    md_output.torque_nm = tq;

    dot = adcs_vec3_dot(&tq, md_input.momentum_nms);
    md_output.dissipative_power = dot;

    if (cmd.saturated_axes != 0U) {
        md_state.saturated_on_cycles++;
    }

    if (md_state.elapsed >= md_config.on_cycles) {
        md_state.rest_target = md_config.rest_cycles +
            md_state.saturated_on_cycles * md_config.extra_rest_per_saturated_cycle;
        md_state.saturated_on_cycles = 0U;
        md_state.mode = MD_REST;
        md_state.elapsed = 0U;
        md_output.mode = MD_REST;
        md_output.elapsed = 0U;
    }

    return;
}

