    md_output.dissipative_power = 0.0;
    return;
}

/* 3. demand begins in IDLE -> ON, this call is cycle one */
if (mode == MD_IDLE) {
    md_state.mode = MD_ON;
    md_state.elapsed = 0U;
    mode = md_state.mode;
}

/* 4. ON */
if (mode == MD_ON) {
    adcs_actuator_command_t cmd;
    adcs_vec3_t torque;
    adcs_status_t st = adcs_momentum_unload_dipole(
        md_input.momentum_nms, md_input.field_body_t,
        md_config.gain_s_inv, md_config.max_dipole_a_m2, &cmd, &torque);
    if (st != ADCS_OK) {
        md_state.mode = MD_FAULT;
        md_state.elapsed = 0U;
        md_output.mode = MD_FAULT;
        md_output.elapsed = 0U;
        md_output.saturation_mask = 0U;
        md_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
        md_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        md_output.dissipative_power = 0.0;
        return;
    }
    md_output.dipole_a_m2 = cmd.command;
    md_output.torque_nm = torque;
    md_output.dissipative_power = adcs_vec3_dot(&torque, md_input.momentum_nms);
    md_output.saturation_mask = cmd.saturated_axes;
    if (cmd.saturated_axes != 0U) {
        md_state.saturated_on_cycles += 1U;
    }
    md_state.elapsed += 1U;
    md_output.mode = MD_ON;
    md_output.elapsed = md_state.elapsed;
    if (md_state.elapsed >= md_config.on_cycles) {
        md_state.rest_target = md_config.rest_cycles +
            md_state.saturated_on_cycles * md_config.extra_rest_per_saturated_cycle;
        md_state.saturated_on_cycles = 0U;
        md_state.mode = MD_REST;
        md_state.elapsed = 0U;
    }
    return;
}

/* 5. REST */
if (mode == MD_REST) {
    md_state.elapsed += 1U;
    md_output.mode = MD_REST;
    md_output.elapsed = md_state.elapsed;
    md_output.saturation_mask = 0U;
    md_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
    md_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    md_output.dissipative_power = 0.0;
    if (md_state.elapsed >= md_state.rest_target) {
        md_state.mode = MD_IDLE;
        md_state.elapsed = 0U;
    }
    return;
}

/* fallback: default to IDLE zero */
md_state.mode = MD_IDLE;
md_state.elapsed = 0U;
md_output.mode = MD_IDLE;
md_output.elapsed = 0U;
md_output.saturation_mask = 0U;
md_output.dipole_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
md_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
md_output.dissipative_power = 0.0;
